import pulp

# ---------- Data ----------
# Vessels, their operation sequences (terminal, processing time)
vessels = {
    1: [("T1", 4), ("T3", 5), ("T2", 6)],
    2: [("T3", 4), ("T2", 1), ("T1", 3)],
    3: [("T1", 2), ("T2", 10), ("T3", 8)],
}

# Build a flat list of operations
# each operation gets a unique id: (vessel, index)
ops = {}
for v, seq in vessels.items():
    for idx, (term, dur) in enumerate(seq, start=1):
        ops[(v, idx)] = {"terminal": term, "proc": dur}

# Set of terminals
terminals = {"T1", "T2", "T3"}

# Big-M (larger than any possible makespan)
M = 100

# ---------- Model ----------
model = pulp.LpProblem("Shipping_Schedule", pulp.LpMinimize)

# Decision variables: start time of each operation (continuous, >=0)
start = {}
for oid in ops:
    start[oid] = pulp.LpVariable(f"start_{oid[0]}_{oid[1]}", lowBound=0, cat="Continuous")

# Binary variables for ordering on each terminal
# y[(i,j,term)] == 1 if operation i precedes operation j on terminal term
y = {}
# For each terminal, collect operations using it
ops_by_term = {t: [] for t in terminals}
for oid, data in ops.items():
    ops_by_term[data["terminal"]].append(oid)

for term, oplist in ops_by_term.items():
    for i in range(len(oplist)):
        for j in range(i + 1, len(oplist)):
            oid_i = oplist[i]
            oid_j = oplist[j]
            y[(oid_i, oid_j, term)] = pulp.LpVariable(
                f"y_{oid_i[0]}_{oid_i[1]}_{oid_j[0]}_{oid_j[1]}_{term}",
                cat="Binary",
            )
            # also need the opposite direction variable implicitly via (1 - y)

# Makespan variable
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat="Continuous")

# ---------- Objective ----------
model += Cmax, "Minimize_makespan"

# ---------- Constraints ----------
# 1. Each vessel's operations must respect their given order
for v, seq in vessels.items():
    for k in range(1, len(seq)):
        oid_prev = (v, k)
        oid_next = (v, k + 1)
        model += (
            start[oid_next] >= start[oid_prev] + ops[oid_prev]["proc"],
            f"precedence_v{v}_op{k}_to_op{k+1}",
        )

# 2. Disjunctive constraints on each terminal (no overlap)
for term, oplist in ops_by_term.items():
    for i in range(len(oplist)):
        for j in range(i + 1, len(oplist)):
            oid_i = oplist[i]
            oid_j = oplist[j]
            # i before j
            model += (
                start[oid_j]
                >= start[oid_i] + ops[oid_i]["proc"] - M * (1 - y[(oid_i, oid_j, term)]),
                f"term_{term}_order_{oid_i}_before_{oid_j}",
            )
            # j before i
            model += (
                start[oid_i]
                >= start[oid_j] + ops[oid_j]["proc"] - M * y[(oid_i, oid_j, term)],
                f"term_{term}_order_{oid_j}_before_{oid_i}",
            )

# 3. Makespan must be at least the completion time of each vessel's last operation
for v, seq in vessels.items():
    last_op = (v, len(seq))
    model += (
        Cmax >= start[last_op] + ops[last_op]["proc"],
        f"makespan_after_v{v}_last",
    )

# ---------- Solve ----------
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# ---------- Output ----------
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Minimum makespan: {pulp.value(Cmax)} hours\n")

print("Start times (hour):")
for oid in sorted(start):
    print(f" Vessel {oid[0]} Op {oid[1]} (Terminal {ops[oid]['terminal']}, "
          f"Dur {ops[oid]['proc']}h) -> start at {pulp.value(start[oid]):.2f}")

import pulp

# ----- Data ---------------------------------------------------------
# Nodes: 0=Alpha, 1=Beta, 2=Gamma, 3=Delta
nodes = [0, 1, 2, 3]
n = len(nodes)

# Travel times (minutes) – symmetric matrix
dist = {
    (0, 1): 184.2, (1, 0): 184.2,
    (0, 2): 71.6,  (2, 0): 71.6,
    (0, 3): 94.6,  (3, 0): 94.6,
    (1, 2): 126.8, (2, 1): 126.8,
    (1, 3): 94.5,  (3, 1): 94.5,
    (2, 3): 64.0,  (3, 2): 64.0
}

# ----- Model ---------------------------------------------------------
model = pulp.LpProblem("Inspection_Circuit", pulp.LpMinimize)

# Decision variables: x[i][j] = 1 if we travel directly from i to j
x = {}
for i in nodes:
    for j in nodes:
        if i != j:
            var_name = f"x_{i}_{j}"
            x[(i, j)] = pulp.LpVariable(var_name, cat="Binary")
        else:
            # No self‑loops; fix to 0 for completeness
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", lowBound=0, upBound=0, cat="Binary")

# MTZ auxiliary variables (continuous)
u = {}
for i in nodes:
    if i == 0:            # depot (Alpha) – fixed to 1
        u[i] = pulp.LpVariable(f"u_{i}", lowBound=1, upBound=1, cat="Continuous")
    else:
        u[i] = pulp.LpVariable(f"u_{i}", lowBound=2, upBound=n, cat="Continuous")

# Objective: minimise total travel time
model += pulp.lpSum(dist[(i, j)] * x[(i, j)] for i in nodes for j in nodes if i != j)

# ----- Constraints ---------------------------------------------------

# 1) Exactly one outgoing arc from each node
for i in nodes:
    model += pulp.lpSum(x[(i, j)] for j in nodes if i != j) == 1

# 2) Exactly one incoming arc to each node
for j in nodes:
    model += pulp.lpSum(x[(i, j)] for i in nodes if i != j) == 1

# 3) MTZ subtour elimination constraints
#    For all i != j, i != 0, j != 0
for i in nodes:
    for j in nodes:
        if i != j and i != 0 and j != 0:
            model += u[i] - u[j] + n * x[(i, j)] <= n - 1

# ----- Solve ---------------------------------------------------------
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# ----- Output --------------------------------------------------------
if pulp.LpStatus[model.status] != "Optimal":
    print("No optimal solution found.")
else:
    total_time = pulp.value(model.objective)
    print(f"Optimal total travel time: {total_time:.2f} minutes")

    # Reconstruct tour starting from Alpha (node 0)
    tour = [0]
    while len(tour) < n:
        last = tour[-1]
        for j in nodes:
            if last != j and pulp.value(x[(last, j)]) > 0.5:
                tour.append(j)
                break
    # Return to start
    tour.append(0)

    name_map = {0: "Alpha", 1: "Beta", 2: "Gamma", 3: "Delta"}
    readable_tour = " -> ".join(name_map[i] for i in tour)
    print("Optimal inspection circuit:")
    print(readable_tour)
